import{_ as e,o as r,c as t,ag as o}from"./chunks/framework.D9ghT4bC.js";const m=JSON.parse('{"title":"在 MacOS 上安装","description":"","frontmatter":{},"headers":[],"relativePath":"zh/Other/Installing-on-macOS.md","filePath":"zh/Other/Installing-on-macOS.md"}'),l={name:"zh/Other/Installing-on-macOS.md"};function n(i,a,c,s,h,p){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="在-macos-上安装" tabindex="-1">在 MacOS 上安装 <a class="header-anchor" href="#在-macos-上安装" aria-label="Permalink to &quot;在 MacOS 上安装&quot;">​</a></h1><p>目前有几种在 MacOS 上安装 Unciv 的方式。</p><p>建议不要从源码安装，因为最终结果是一样的。</p><h2 id="使用-macports-安装" tabindex="-1">使用 MacPorts 安装 <a class="header-anchor" href="#使用-macports-安装" aria-label="Permalink to &quot;使用 MacPorts 安装&quot;">​</a></h2><p>详情见<a href="https://ports.macports.org/port/unciv/" target="_blank" rel="noreferrer">这里</a>——只需在命令行运行 <code>sudo port install unciv</code> 即可！</p><p>不需要预装 JDK。</p><h2 id="使用-jar-安装" tabindex="-1">使用 JAR 安装 <a class="header-anchor" href="#使用-jar-安装" aria-label="Permalink to &quot;使用 JAR 安装&quot;">​</a></h2><ol><li>如果你的 Mac 上还没有安装 Java 8 或 OpenJDK（11 和 18 版本也能用），要么</li></ol><ul><li>从<a href="https://java.com/en/download/" target="_blank" rel="noreferrer">官方网站</a>下载。下载完成后打开它，按屏幕提示操作。</li><li>如果你用 <a href="https://brew.sh/" target="_blank" rel="noreferrer">Homebrew</a>，直接运行 <code>brew install java</code></li></ul><ol start="2"><li>装好 Java 后，就可以下载最新的 Unciv JAR 了。可以从 Github 的 <a href="https://github.com/yairm210/Unciv/releases" target="_blank" rel="noreferrer">releases</a> 页面下载名为 <em>Unciv.jar</em> 的文件。</li><li>要运行游戏，需要在终端运行 <code>java -jar Unciv.jar</code>。</li><li>或者，你可以创建一个包含该命令的 &#39;Unciv.sh&#39; 文件，然后运行这个新文件，这样可以创建快捷方式等。</li></ol><p><em>（遗憾的是，用这种方法在 MacOS 上安装时 Unciv 不会自动更新，所以每次想更新游戏都得从 Github 下载最新的 Unciv.jar。）</em></p><h2 id="从源码安装" tabindex="-1">从源码安装 <a class="header-anchor" href="#从源码安装" aria-label="Permalink to &quot;从源码安装&quot;">​</a></h2><p>如何从源码安装 Unciv 请参见<a href="./../Developers/Building-Locally.html">不使用 Android Studio 进行本地构建</a>。不建议使用这种方法，因为它和第一种方法结果相同，却要复杂得多，而且过程中容易出错。</p><p><em>（遗憾的是，用这种方法在 MacOS 上安装时 Unciv 不会自动更新，所以每次想更新游戏都得重复这些步骤。）</em></p>',14)])])}const _=e(l,[["render",n]]);export{m as __pageData,_ as default};
